CREATE OR REPLACE PROCEDURE sp(para_ResID integer, para_ResName text, para_Address text, para_StuID integer, para_LName text, para_ResTypeID integer)
LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "Student" WHERE "StuID" = para_StuID) THEN
    UPDATE "Student" SET "LName" = 'BULK_PROCESSED' WHERE "StuID" >= para_StuID;
    UPDATE "Student" SET "Age" = "Age" + 1 WHERE "LName" = para_LName AND "StuID" < para_StuID;
  ELSIF EXISTS (SELECT 1 FROM "Restaurant" WHERE "ResID" = para_ResID) THEN
    UPDATE "Restaurant" SET
      "Address" = 'PENDING',
      "ResName" = CASE WHEN para_ResTypeID < 100 THEN "ResName" || ' [ALT]' ELSE "ResName" END
    WHERE "ResID" <> para_ResID AND "ResName" LIKE para_ResName AND "Address" <> para_Address;
    DELETE FROM "Restaurant" WHERE "ResID" <> para_ResID AND "ResName" LIKE para_ResName AND "Address" = para_Address;
  ELSE
    INSERT INTO "Restaurant_Type" ("ResTypeID", "ResTypeName", "ResTypeDescription")
      SELECT "ResTypeID" + 10, "ResTypeName", "ResTypeDescription" FROM "Restaurant_Type";
    DELETE FROM "Restaurant_Type";
  END IF;
END;
$$;

